'use strict';
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if('IntersectionObserver' in window && !reduced){document.documentElement.classList.add('js');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const progress=document.querySelector('.progress');let ticking=false;function updateProgress(){const height=document.documentElement.scrollHeight-innerHeight;progress.style.width=(height>0?scrollY/height*100:0)+'%';ticking=false;}window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateProgress);ticking=true;}},{passive:true});updateProgress();
function updateTime(){document.querySelector('.time').textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(new Date())+' IST';}updateTime();setInterval(updateTime,60000);document.querySelector('#year').textContent=new Date().getFullYear();
const gameCaptions={'Badly Explained':'Animated movies. Questionable descriptions. Five rounds.','Superheroes':'Marvel and DC frames. A little more revealed with every guess.','Albumnesia':'Album covers. Five seconds to remember. Five seconds to guess.'};
document.querySelectorAll('[data-game]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-game]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('.game-caption').textContent=gameCaptions[button.dataset.game];}));
const ragCaptions={'Naive RAG':'Retrieve once, then generate an answer from the matched context.','Multi-query RAG':'Rephrase the question, retrieve across variations, then merge the context.','ReAct RAG':'Alternate reasoning and retrieval steps to gather useful context.'};
document.querySelectorAll('[data-rag]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-rag]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('.rag-caption').textContent=ragCaptions[button.dataset.rag];}));
let toastTimer;document.querySelector('#copy-email').addEventListener('click',async()=>{const toast=document.querySelector('.toast');try{await navigator.clipboard.writeText('ashish.ch2916@gmail.com');toast.textContent='Email copied. Say hello!';}catch{toast.textContent='ashish.ch2916@gmail.com';}toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500);});
// All content stays accessible without hover or a precise pointer.
const projectCards=[...document.querySelectorAll('.project')];document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});let count=0;projectCards.forEach(card=>{card.hidden=filter!=='all'&&!card.dataset.category.split(' ').includes(filter);if(!card.hidden){count++;card.classList.add('visible');}});document.querySelector('.filter-count').textContent=count+' selected project'+(count===1?'':'s');updateProgress();}));
const stepDescriptions={query:'Start with the question. Its wording affects what the system retrieves.',retrieve:'Search the indexed document chunks for relevant supporting context.',rerank:'Reorder candidate chunks to put the most relevant evidence first.',generate:'Use the selected context to produce an answer, then evaluate its quality.'};document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('.step-caption').textContent=stepDescriptions[button.dataset.step];}));
document.querySelectorAll('.skill-group').forEach(group=>group.addEventListener('toggle',updateProgress));
if(!reduced&&matchMedia('(hover: hover) and (pointer: fine)').matches){document.querySelectorAll('[data-tilt]').forEach(card=>{let frame;card.addEventListener('pointermove',event=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=card.getBoundingClientRect();const x=(event.clientX-r.left)/r.width-.5;const y=(event.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1000px) rotateX(${-y*5}deg) rotateY(${x*5}deg) translateY(-4px)`;});});card.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);card.style.transform='';});});document.querySelectorAll('.magnetic').forEach(link=>{link.addEventListener('pointermove',event=>{const r=link.getBoundingClientRect();link.style.transform=`translate(${(event.clientX-r.left-r.width/2)*.12}px, ${(event.clientY-r.top-r.height/2)*.18}px)`;});link.addEventListener('pointerleave',()=>link.style.transform='');});const cursor=document.querySelector('.cursor-label');document.querySelectorAll('.project-links a').forEach(link=>{link.addEventListener('pointerenter',()=>cursor.classList.add('show'));link.addEventListener('pointerleave',()=>cursor.classList.remove('show'));link.addEventListener('pointermove',event=>{cursor.style.left=event.clientX+'px';cursor.style.top=event.clientY+'px';});});const heroImage=document.querySelector('.hero-art img');let heroFrame;window.addEventListener('scroll',()=>{if(scrollY<850&&!heroFrame){heroFrame=requestAnimationFrame(()=>{heroImage.style.transform=`translateY(${scrollY*.12}px) scale(1.06)`;heroFrame=null;});}},{passive:true});}
